WITH points AS (
SELECT dt,label('host') host,name,multiIf(name='duplika_access_coverage_complete',minMerge(value_min),name IN ('duplika_collector_failed_components','duplika_lve_sample_failed','duplika_lve_sample_age_seconds','duplika_storage_probe_failures','duplika_lve_accounts_observed'),maxMerge(value_max),avgMerge(value_avg)) v FROM {{source}}
WHERE dt >= greatest({{start_time}}, {{end_time}} - INTERVAL 15 MINUTE) AND dt < {{end_time}} [[ AND match(label('host'), {{servidor}}) ]] AND name IN ('duplika_collector_heartbeat','duplika_collector_failed_components','duplika_access_coverage_complete','duplika_lve_sample_failed','duplika_lve_accounts_observed','duplika_lve_sample_age_seconds','duplika_storage_probe_failures')
GROUP BY dt,host,name),
last AS (SELECT host,max(dt) at,if(countIf(name = 'duplika_collector_failed_components') > 0, argMaxIf(v, dt, name = 'duplika_collector_failed_components'), NULL) failures,if(countIf(name = 'duplika_access_coverage_complete') > 0, argMaxIf(v, dt, name = 'duplika_access_coverage_complete'), NULL) coverage,if(countIf(name = 'duplika_lve_sample_failed') > 0, argMaxIf(v, dt, name = 'duplika_lve_sample_failed'), NULL) lve_failed,if(countIf(name = 'duplika_lve_sample_age_seconds') > 0, argMaxIf(v, dt, name = 'duplika_lve_sample_age_seconds'), NULL) lve_age,if(countIf(name = 'duplika_storage_probe_failures') > 0, argMaxIf(v, dt, name = 'duplika_storage_probe_failures'), NULL) storage_failed,if(countIf(name='duplika_lve_accounts_observed')>0,argMaxIf(v,dt,name='duplika_lve_accounts_observed'),NULL) AS observed,if(countIf(name='duplika_lve_accounts_observed')>0,maxIf(dt,name='duplika_lve_accounts_observed'),NULL) AS lve_at FROM points GROUP BY host)
SELECT e.Servidor,l.at AS Inicio_ultimo_bloque,dateDiff('second',l.at,{{end_time}}) AS Edad_del_bloque_segundos,l.failures AS Componentes_fallidos_max_bloque,l.coverage AS Cobertura_minima_bloque,l.lve_failed AS Fallo_LVE_max_bloque,l.observed AS LVEs_observados_max_bloque,l.lve_at AS Inicio_bloque_LVE,if(l.lve_at IS NULL,NULL,l.lve_age) AS Edad_LVE_max_bloque_segundos,l.storage_failed AS Fallos_almacenamiento_max_bloque
FROM (SELECT DISTINCT label('host') AS Servidor FROM {{source}}
WHERE dt >= {{end_time}} - INTERVAL 30 DAY AND dt < {{end_time}}
AND name='memory_total_bytes' AND metrics_count>0) e LEFT JOIN last l ON e.Servidor=l.host
[[ WHERE match(e.Servidor, {{servidor}}) ]]
ORDER BY Servidor SETTINGS join_use_nulls=1
